alter table public.listings add column equipment_category text,add column part_group text;
alter table public.listings add constraint listings_part_equipment check(equipment_category is null or equipment_category in ('Ekskavatör','Mini ekskavatör','Lastikli ekskavatör','Uzun bom ekskavatör','Amfibik ekskavatör','Beko Loder','Lastikli yükleyici','Mini yükleyici','Paletli yükleyici','Dozer','Greyder','Skreyper','Trencher (kanal kazıcı)','Manitou / teleskopik yükleyici','Forklift','İstif makinesi','Reach truck','Transpalet','Vinç','Mobil vinç','Paletli vinç','Kule vinç','Hiab / araç üstü vinç','Sepetli platform','Makaslı platform','Eklemli / teleskopik platform','Beton (mikser ve pompa)','Transmikser','Beton pompası','Sabit beton pompası','Beton santrali','Beton serme makinesi','Shotcrete / püskürtme beton makinesi','Kamyon','Damperli kamyon','Kırkayak kamyon','Çekici (tır)','Kurtarıcı (oto çekici)','Lowbed','Dorse / römork','Tanker','Arazöz / su tankeri','Belden kırma kaya kamyonu','Rijit kaya kamyonu','Silindir','Kompaktör','Asfalt finişeri','Asfalt frezesi','Asfalt distribütörü','Yol süpürme aracı','Zemin stabilizasyon makinesi','Yol çizgi makinesi','Fore kazık makinesi','Mini kazık / ankraj makinesi','Diyafram duvar makinesi','Sondaj makinesi','Tünel açma makinesi (TBM)','Delici jumbo','Kırıcı / delici ataşman','Kırma eleme tesisi','Taş kırma makinesi','Elek / yıkama tesisi','Konveyör / bant sistemi','Jeneratör','Kompresör','Motopomp / su pompası','Işık kulesi','Kaynak makinesi','Endüstriyel temizlik makinesi','Traktör','Biçerdöver','Tarım makinesi / ekipmanı','Orman makinesi','Liman / konteyner elleçleme makinesi','Diğer iş makinesi')),add constraint listings_part_group check(part_group is null or part_group in ('engine','hydraulics','undercarriage','transmission','brakes','electrical','cooling','fuel','filters','seals','body','attachments','lifting','tires','exhaust','other')),add constraint listings_part_fields_only check((equipment_category is null and part_group is null) or category in ('Yedek parça','Lastik ve jant'));
grant select(equipment_category,part_group) on public.listings to anon,authenticated;
grant update(equipment_category,part_group) on public.listings to authenticated;
create index listings_parts_filter on public.listings(equipment_category,part_group,city,created_at desc) where status='active' and category in ('Yedek parça','Lastik ve jant');
